arguments.file_text:
namespace sv_e445026b3d7e4fedb6d768ec648b7828.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

public static class TimeFormatHelper
{
    public static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.chat-layout {
    height: 100vh;
    overflow: hidden;
}

.message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #e0e0e0;
    background: #fff;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input textarea:focus {
    border-color: #5865f2;
}

.btn-send {
    align-self: flex-end;
    padding: 0.5rem 1.25rem;
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-send:hover:not(:disabled) {
    background: #4752c4;
}

.btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@using sv_e445026b3d7e4fedb6d768ec648b7828.Services

<div class="message-bubble"
     @onmouseenter="ShowActions"
     @onmouseleave="HideActions">
    <div class="message-header">
        <span class="author">@Message.Author</span>
        <span class="timestamp">@TimeFormatHelper.FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="OnViewThread">
            💬 @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button @onclick="OnReply" title="Reply in thread">💬</button>
            <button @onclick="ToggleEmojiPicker" title="Add reaction">😀</button>
        </div>

        @if (showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in CommonEmojis)
                {
                    <button @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback OnReply { get; set; }
    [Parameter] public EventCallback OnViewThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private static readonly string[] CommonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ShowActions() => showActions = true;

    private void HideActions()
    {
        showActions = false;
        showEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }
}

.message-bubble {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #f2f3f5;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a2e;
}

.timestamp {
    font-size: 0.75rem;
    color: #8e9297;
}

.message-content {
    font-size: 0.9rem;
    color: #2e3338;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    background: #e3e5e8;
    border: 1px solid #d0d2d5;
    border-radius: 999px;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #c8ccd1;
}

.thread-link {
    display: inline-block;
    margin-top: 0.3rem;
    padding: 0;
    font-size: 0.8rem;
    font-weight: 600;
    color: #5865f2;
    background: none;
    border: none;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.15rem;
    padding: 0.15rem;
    background: #fff;
    border: 1px solid #d0d2d5;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.message-actions button {
    padding: 0.2rem 0.4rem;
    font-size: 1rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.message-actions button:hover {
    background: #e3e5e8;
}

.emoji-picker {
    position: absolute;
    top: -0.5rem;
    right: 5rem;
    display: flex;
    gap: 0.15rem;
    padding: 0.3rem;
    background: #fff;
    border: 1px solid #d0d2d5;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 10;
}

.emoji-picker button {
    padding: 0.25rem;
    font-size: 1.2rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.emoji-picker button:hover {
    background: #e3e5e8;
}

@using sv_e445026b3d7e4fedb6d768ec648b7828.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrEmpty(channel.Description))
                {
                    <div class="channel-desc">@Truncate(channel.Description, 50)</div>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength)
        => text.Length > maxLength ? string.Concat(text.AsSpan(0, maxLength - 3), "...") : text;
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    color: #f2f3f5;
    overflow: hidden;
}

.sidebar-header {
    padding: 1rem;
    border-bottom: 1px solid #3f4147;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0.5rem;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 0.5rem 0.75rem;
    margin-bottom: 2px;
    background: none;
    border: none;
    border-radius: 4px;
    color: #949ba4;
    cursor: pointer;
    transition: background 0.1s, color 0.1s;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.unread-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.25rem;
    height: 1.25rem;
    padding: 0 0.35rem;
    font-size: 0.7rem;
    font-weight: 700;
    color: #fff;
    background: #ed4245;
    border-radius: 999px;
}

.channel-desc {
    font-size: 0.75rem;
    color: #6d6f78;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@using sv_e445026b3d7e4fedb6d768ec648b7828.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="btn-close-thread" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <div class="root-header">
                <span class="author">@RootMessage.Author</span>
                <span class="timestamp">@TimeFormatHelper.FormatRelativeTime(RootMessage.SentAt)</span>
            </div>
            <div class="root-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="reply-header">
                        <span class="author">@reply.Author</span>
                        <span class="timestamp">@TimeFormatHelper.FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="reply-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply..." ButtonText="Reply" OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
}

.thread-panel {
    display: flex;
