toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #f2f3f5;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a2e;
}

.timestamp {
    font-size: 0.75rem;
    color: #8e9297;
}

.message-content {
    font-size: 0.9rem;
    color: #2e3338;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    background: #e3e5e8;
    border: 1px solid #d0d2d5;
    border-radius: 999px;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #c8ccd1;
}

.thread-link {
    display: inline-block;
    margin-top: 0.3rem;
    padding: 0;
    font-size: 0.8rem;
    font-weight: 600;
    color: #5865f2;
    background: none;
    border: none;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.15rem;
    padding: 0.15rem;
    background: #fff;
    border: 1px solid #d0d2d5;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.message-actions button {
    padding: 0.2rem 0.4rem;
    font-size: 1rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.message-actions button:hover {
    background: #e3e5e8;
}

.emoji-picker {
    position: absolute;
    top: -0.5rem;
    right: 5rem;
    display: flex;
    gap: 0.15rem;
    padding: 0.3rem;
    background: #fff;
    border: 1px solid #d0d2d5;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 10;
}

.emoji-picker button {
    padding: 0.25rem;
    font-size: 1.2rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.emoji-picker button:hover {
    background: #e3e5e8;
}

