toolArgs.file_text:
@using sv_e445026b3d7e4fedb6d768ec648b7828.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrEmpty(channel.Description))
                {
                    <div class="channel-desc">@Truncate(channel.Description, 50)</div>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength)
        => text.Length > maxLength ? string.Concat(text.AsSpan(0, maxLength - 3), "...") : text;
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    color: #f2f3f5;
    overflow: hidden;
}

.sidebar-header {
    padding: 1rem;
    border-bottom: 1px solid #3f4147;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0.5rem;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    padding: 0.5rem 0.75rem;
    margin-bottom: 2px;
    background: none;
    border: none;
    border-radius: 4px;
    color: #949ba4;
    cursor: pointer;
    transition: background 0.1s, color 0.1s;
}

.channel-item:hover {
    background: #35373c;
    color: #dbdee1;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.unread-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.25rem;
    height: 1.25rem;
    padding: 0 0.35rem;
    font-size: 0.7rem;
    font-weight: 700;
    color: #fff;
    background: #ed4245;
    border-radius: 999px;
}

.channel-desc {
    font-size: 0.75rem;
    color: #6d6f78;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

