arguments.file_text:
@page "/chat"
@layout sv_e445026b3d7e4fedb6d768ec648b7828.Components.Chat.ChatLayout
@using sv_e445026b3d7e4fedb6d768ec648b7828.Services
@using sv_e445026b3d7e4fedb6d768ec648b7828.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="message-area @(isThreadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="area-header">
                <h3># @selectedChannel.Name</h3>
                <p>@selectedChannel.Description</p>
            </div>

            <div class="message-list">
                @if (hasMoreMessages)
                {
                    <div class="load-more-row">
                        <button class="btn-load-more" @onclick="LoadMoreMessages" disabled="@loadingMore">
                            @(loadingMore ? "Loading..." : "Load older messages")
                        </button>
                    </div>
                }

                @foreach (var message in messages)
                {
                    <MessageBubble Message="message"
                                   ReplyCount="GetReplyCount(message.Id)"
                                   OnReply="() => OpenThread(message)"
                                   OnViewThread="() => OpenThread(message)"
                                   OnReact="(emoji) => AddReaction(message.Id, emoji)" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")" OnSubmit="SendMessage" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="thread-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private int selectedChannelId;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = new();

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private int skip;
    private const int PageSize = 50;
    private bool hasMoreMessages;
    private bool loadingMore;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        skip = 0;

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = messages.Count == PageSize;
        skip = messages.Count;

        BuildThreadReplyCounts();
        CloseThread();
        await ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMoreMessages()
    {
        loadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId, skip, PageSize);
        hasMoreMessages = older.Count == PageSize;
        messages.InsertRange(0, older);
        skip += older.Count;
        BuildThreadReplyCounts();
        loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        var thread = await ChatService.GetThreadAsync(rootMessage.Id);
        threadMessages = thread.Where(m => m.Id != rootMessage.Id).ToList();
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        threadReplyCounts[threadRootMessage.Id] =
            threadReplyCounts.GetValueOrDefault(threadRootMessage.Id) + 1;
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        var msg = messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private int GetReplyCount(int messageId)
        => threadReplyCounts.GetValueOrDefault(messageId);

    private void BuildThreadReplyCounts()
    {
        threadReplyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            threadReplyCounts[msg.ReplyToId!.Value] =
                threadReplyCounts.GetValueOrDefault(msg.ReplyToId!.Value) + 1;
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.message-area.expanded {
    /* takes remaining space when thread is closed */
}

