    background: #fff;
}

.area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a2e;
}

.area-header p {
    margin: 0.15rem 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.load-more-row {
    display: flex;
    justify-content: center;
    padding: 0.5rem;
}

.btn-load-more {
    padding: 0.35rem 1rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: #5865f2;
    background: none;
    border: 1px solid #5865f2;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.1s;
}

.btn-load-more:hover:not(:disabled) {
    background: #eef0ff;
}

.btn-load-more:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #8e9297;
    font-size: 1rem;
}

